export const EVIDENCE_DOCS: Record<string, string> = {
  "synthetic_data/DOC-RFC-102.md": "# RFC-102: Payments Service Architecture Overview\n\n- **Document ID**: `DOC-RFC-102`\n- **Author**: Sarah Kim (Senior Staff Engineer, Monetization Team)\n- **Date**: 2024-03-10\n- **Status**: Historical / Deprecated Configuration Reference\n\n## 1. Overview\nThe Payments Service (`payments-svc`) handles credit card transactions, subscription charges, and third-party merchant reconciliation for Nexora Cloud. \n\n## 2. Authentication Protocol (Section 4.2)\n> \"All incoming inter-service requests to the Payments API MUST authenticate against the Identity Service (`identity-svc`) using the standard **AUTH-V1** shared symmetric key and legacy HMAC signature header (`X-Nexora-Auth-V1`). Requests without this signature will be rejected with HTTP 401.\"\n\n## 3. Dependencies\n- Upstream: `checkout-web`, `billing-svc`\n- Downstream: `identity-svc`, `ledger-svc`\n",
  "synthetic_data/DOC-DEC-042.md": "# ADR-042: Migration from AUTH-V1 to Asymmetric AUTH-V2\n\n- **Decision ID**: `DEC-042`\n- **Document ID**: `DOC-DEC-042`\n- **Author**: Marcus Vance (Principal Architect, Core Platform)\n- **Approved By**: Alex Chen (VP of Engineering)\n- **Approved Date**: 2026-09-15\n- **Status**: Approved / Current Policy\n\n## 1. Context\nFollowing the P0 outage during Incident INC-8812, shared symmetric keys in AUTH-V1 were identified as a critical vulnerability and latency bottleneck.\n\n## 2. Decision\n> \"All tier-1 services, specifically including `payments-svc` and `identity-svc`, are REQUIRED to adopt **AUTH-V2** (asymmetric RS256 JWT tokens with automatic public-key rotation every 24 hours). Legacy AUTH-V1 endpoints will be deprecated and deactivated on November 1, 2026.\"\n\n## 3. Implementation Lead\nElena Rostova (Tech Lead, Core Platform) is designated as the migration owner.\n",
  "synthetic_data/DOC-INC-8812.md": "# Post-Mortem: Incident INC-8812 (Payments Auth Failure)\n\n- **Incident ID**: `INC-8812`\n- **Severity**: P0 (Revenue Impacting)\n- **Occurred**: 2026-08-20T14:22:00Z\n- **Resolved**: 2026-08-20T17:45:00Z\n- **Incident Commander**: Elena Rostova (Core Platform)\n- **Participating Engineers**: Sarah Kim (Monetization), David Kumar (Infrastructure)\n\n## 1. Summary\nA catastrophic cascade of authentication timeouts occurred between `payments-svc` and `identity-svc` when legacy AUTH-V1 shared keys expired without graceful rotation. Over 42,000 checkout attempts failed before manual rollback.\n\n## 2. Root Cause\n`payments-svc` relied on static AUTH-V1 HMAC validation. When Identity rotated its key buffer, Payments rejected valid user tokens.\n\n## 3. Corrective Actions\n1. Emergency hotfix deployed by Elena Rostova.\n2. Architecture team commanded to draft ADR-042 requiring AUTH-V2 across all payments and identity pathways.\n",
  "doc_rfc102": "# RFC-102: Payments Service Architecture Overview\n\n- **Document ID**: `DOC-RFC-102`\n- **Author**: Sarah Kim (Senior Staff Engineer, Monetization Team)\n- **Date**: 2024-03-10\n- **Status**: Historical / Deprecated Configuration Reference\n\n## 1. Overview\nThe Payments Service (`payments-svc`) handles credit card transactions, subscription charges, and third-party merchant reconciliation for Nexora Cloud. \n\n## 2. Authentication Protocol (Section 4.2)\n> \"All incoming inter-service requests to the Payments API MUST authenticate against the Identity Service (`identity-svc`) using the standard **AUTH-V1** shared symmetric key and legacy HMAC signature header (`X-Nexora-Auth-V1`). Requests without this signature will be rejected with HTTP 401.\"\n\n## 3. Dependencies\n- Upstream: `checkout-web`, `billing-svc`\n- Downstream: `identity-svc`, `ledger-svc`\n",
  "doc_adr042": "# ADR-042: Migration from AUTH-V1 to Asymmetric AUTH-V2\n\n- **Decision ID**: `DEC-042`\n- **Document ID**: `DOC-DEC-042`\n- **Author**: Marcus Vance (Principal Architect, Core Platform)\n- **Approved By**: Alex Chen (VP of Engineering)\n- **Approved Date**: 2026-09-15\n- **Status**: Approved / Current Policy\n\n## 1. Context\nFollowing the P0 outage during Incident INC-8812, shared symmetric keys in AUTH-V1 were identified as a critical vulnerability and latency bottleneck.\n\n## 2. Decision\n> \"All tier-1 services, specifically including `payments-svc` and `identity-svc`, are REQUIRED to adopt **AUTH-V2** (asymmetric RS256 JWT tokens with automatic public-key rotation every 24 hours). Legacy AUTH-V1 endpoints will be deprecated and deactivated on November 1, 2026.\"\n\n## 3. Implementation Lead\nElena Rostova (Tech Lead, Core Platform) is designated as the migration owner.\n",
  "doc_inc8812": "# Post-Mortem: Incident INC-8812 (Payments Auth Failure)\n\n- **Incident ID**: `INC-8812`\n- **Severity**: P0 (Revenue Impacting)\n- **Occurred**: 2026-08-20T14:22:00Z\n- **Resolved**: 2026-08-20T17:45:00Z\n- **Incident Commander**: Elena Rostova (Core Platform)\n- **Participating Engineers**: Sarah Kim (Monetization), David Kumar (Infrastructure)\n\n## 1. Summary\nA catastrophic cascade of authentication timeouts occurred between `payments-svc` and `identity-svc` when legacy AUTH-V1 shared keys expired without graceful rotation. Over 42,000 checkout attempts failed before manual rollback.\n\n## 2. Root Cause\n`payments-svc` relied on static AUTH-V1 HMAC validation. When Identity rotated its key buffer, Payments rejected valid user tokens.\n\n## 3. Corrective Actions\n1. Emergency hotfix deployed by Elena Rostova.\n2. Architecture team commanded to draft ADR-042 requiring AUTH-V2 across all payments and identity pathways.\n",
  "RFC-102": "# RFC-102: Payments Service Architecture Overview\n\n- **Document ID**: `DOC-RFC-102`\n- **Author**: Sarah Kim (Senior Staff Engineer, Monetization Team)\n- **Date**: 2024-03-10\n- **Status**: Historical / Deprecated Configuration Reference\n\n## 1. Overview\nThe Payments Service (`payments-svc`) handles credit card transactions, subscription charges, and third-party merchant reconciliation for Nexora Cloud. \n\n## 2. Authentication Protocol (Section 4.2)\n> \"All incoming inter-service requests to the Payments API MUST authenticate against the Identity Service (`identity-svc`) using the standard **AUTH-V1** shared symmetric key and legacy HMAC signature header (`X-Nexora-Auth-V1`). Requests without this signature will be rejected with HTTP 401.\"\n\n## 3. Dependencies\n- Upstream: `checkout-web`, `billing-svc`\n- Downstream: `identity-svc`, `ledger-svc`\n",
  "ADR-042": "# ADR-042: Migration from AUTH-V1 to Asymmetric AUTH-V2\n\n- **Decision ID**: `DEC-042`\n- **Document ID**: `DOC-DEC-042`\n- **Author**: Marcus Vance (Principal Architect, Core Platform)\n- **Approved By**: Alex Chen (VP of Engineering)\n- **Approved Date**: 2026-09-15\n- **Status**: Approved / Current Policy\n\n## 1. Context\nFollowing the P0 outage during Incident INC-8812, shared symmetric keys in AUTH-V1 were identified as a critical vulnerability and latency bottleneck.\n\n## 2. Decision\n> \"All tier-1 services, specifically including `payments-svc` and `identity-svc`, are REQUIRED to adopt **AUTH-V2** (asymmetric RS256 JWT tokens with automatic public-key rotation every 24 hours). Legacy AUTH-V1 endpoints will be deprecated and deactivated on November 1, 2026.\"\n\n## 3. Implementation Lead\nElena Rostova (Tech Lead, Core Platform) is designated as the migration owner.\n",
  "INC-8812": "# Post-Mortem: Incident INC-8812 (Payments Auth Failure)\n\n- **Incident ID**: `INC-8812`\n- **Severity**: P0 (Revenue Impacting)\n- **Occurred**: 2026-08-20T14:22:00Z\n- **Resolved**: 2026-08-20T17:45:00Z\n- **Incident Commander**: Elena Rostova (Core Platform)\n- **Participating Engineers**: Sarah Kim (Monetization), David Kumar (Infrastructure)\n\n## 1. Summary\nA catastrophic cascade of authentication timeouts occurred between `payments-svc` and `identity-svc` when legacy AUTH-V1 shared keys expired without graceful rotation. Over 42,000 checkout attempts failed before manual rollback.\n\n## 2. Root Cause\n`payments-svc` relied on static AUTH-V1 HMAC validation. When Identity rotated its key buffer, Payments rejected valid user tokens.\n\n## 3. Corrective Actions\n1. Emergency hotfix deployed by Elena Rostova.\n2. Architecture team commanded to draft ADR-042 requiring AUTH-V2 across all payments and identity pathways.\n",
};

export function getMockInvestigation(question: string, mode?: string): InvestigationResponse {
  const lowerQ = question.toLowerCase();
  const activeMode = mode || (lowerQ.includes("pr #318") || lowerQ.includes("architect") ? "architect" : lowerQ.includes("p0") || lowerQ.includes("incident") ? "incident" : "overview");
  
  if (activeMode === "architect" || lowerQ.includes("pr #318") || lowerQ.includes("drift") || lowerQ.includes("hmac")) {
    return { ...DEFAULT_INVESTIGATION_ARCHITECT, question };
  }
  if (activeMode === "incident" || lowerQ.includes("p0") || lowerQ.includes("outage") || lowerQ.includes("cascade") || lowerQ.includes("blast")) {
    return { ...DEFAULT_INVESTIGATION_INCIDENT, question };
  }
  return { ...DEFAULT_INVESTIGATION_OVERVIEW, question };
}

export function getMockEvidence(uri: string): string {
  const key = Object.keys(EVIDENCE_DOCS).find(k => uri.includes(k) || k.includes(uri));
  return key ? EVIDENCE_DOCS[key] : "# Evidence Record\n\nDocument uri: " + uri + "\n\nSource provenance verified in FalkorDB Graph.";
}

export function getMockChatReply(message: string, model: string = "Meta Llama 3.2 (Open Source)"): { reply: string; model_used: string; latency_ms: number } {
  const lower = message.toLowerCase();
  let reply = "";
  if (lower.includes("pr #318") || lower.includes("blocked") || lower.includes("drift") || lower.includes("hmac")) {
    reply = `### 🛡️ Architectural Drift Review: PR #318

❌ **Status**: Merge Blocked by AI Staff Architect Guard

- **Target Service**: \`payments-svc\` (Tier 1, P0 Criticality)
- **Violation**: Attempts to revert inter-service authentication to legacy symmetric HMAC keys (AUTH-V1).
- **Governing Policy**: **ADR-042** (*Migration to Asymmetric RS256 Auth-V2*, approved by Alex Chen, authored by Marcus Vance).
- **Historical Outage Risk**: Reverting to AUTH-V1 revives the root cause of **Incident INC-8812** (a 3.5-hour revenue outage causing 42k checkout failures).
- **Action**: Reject PR #318. Maintain RS256 token validation with 24h key rotation.`;
  } else if (lower.includes("blast") || lower.includes("incident") || lower.includes("p0") || lower.includes("outage")) {
    reply = `### 🚨 P0 Incident Analysis: payments-svc

- **Direct Impact**: Payments Service failure directly disrupts:
  1. \`checkout-web\` (Tier 1, **P0**) — 1 hop via GraphQL
  2. \`billing-svc\` (Tier 1, **P1**) — 1 hop via REST (exponential retry)
  3. \`notification-svc\` (Tier 2, **P2**) — 2 hops via EventBridge
- **Historical Precedent**: **INC-8812** (matching auth timeout cascade).
- **Mobilized Incident Commander**: **Elena Rostova** (Tech Lead, Core Platform, \`#war-room-payments\`).`;
  } else if (lower.includes("who owns") || lower.includes("ownership") || lower.includes("team")) {
    reply = `### 🏢 Service Ownership: Payments Service

- **Owning Team**: **Core Platform** (\`#platform-core\`)
- **Engineering Leads**: Elena Rostova (Tech Lead), Marcus Vance (Principal Architect)
- **Department**: Infrastructure Engineering
- **Direct Dependencies**: \`identity-svc\` (gRPC), \`ledger-svc\` (gRPC)`;
  } else {
    reply = `### 🧠 FalkorDB Knowledge Graph Synthesis

Based on live graph traversal across Nexora Cloud topology:
- **Services Tracked**: 6 microservices (\`payments-svc\`, \`identity-svc\`, \`checkout-web\`, \`billing-svc\`, \`ledger-svc\`, \`notification-svc\`)
- **Active Governance**: ADR-042 enforces RS256 asymmetric authentication across Tier-1 microservices.
- **Transitive Depth**: Arbitrary-depth dependency traversal running under 15ms via GraphBLAS sparse matrix linear algebra.`;
  }

  return {
    reply,
    model_used: `${model} (FalkorDB Graph-RAG Engine)`,
    latency_ms: 8.7,
  };
}

